//! Localized month and weekday names of every locale the JDK formats
//! with (CLDR 46, the JDK's default locale data), generated from the
//! `cldr-dates-full` 46.0.0 package (`ca-gregorian.json`: months and days,
//! format and stand-alone, wide and abbreviated) and day periods (AM/PM,
//! format wide, what the JDK's `a` prints). Shared by the ingest date
//! processors and date mapping parsing. Regenerated by
//! `tools/locale_names_tsv.py`.

/// A locale's raw names: months (format wide, format abbreviated,
/// stand-alone wide, stand-alone abbreviated; 12 each), then weekdays
/// Monday first (the same four forms; 7 each), then AM, PM.
pub fn rows(locale: &str) -> Option<&'static [Vec<&'static str>]> {
    let mut tag = locale.replace('_', "-");
    for (old, new) in [("iw", "he"), ("in", "id"), ("ji", "yi")] {
        if tag == old || tag.starts_with(&format!("{old}-")) {
            tag = format!("{new}{}", &tag[old.len()..]);
        }
    }
    let table = locale_dates();
    let mut cur = tag.as_str();
    loop {
        if let Some(r) = table.get(cur).or_else(|| table.iter().find(|(k, _)| k.eq_ignore_ascii_case(cur)).map(|(_, v)| v)) {
            return Some(r.as_slice());
        }
        cur = &cur[..cur.rfind('-')?];
    }
}

/// Month and weekday names of every locale the JDK formats with (CLDR 46,
/// the JDK's default locale data): per locale, months (format wide, format
/// abbreviated, stand-alone wide, stand-alone abbreviated) and weekdays
/// Monday first (same four forms). A locale identical to its parent is
/// omitted and resolves to it.
const LOCALE_DATES: &str = include_str!("locale_names.tsv");

fn locale_dates() -> &'static std::collections::HashMap<&'static str, Vec<Vec<&'static str>>> {
    static T: std::sync::OnceLock<std::collections::HashMap<&'static str, Vec<Vec<&'static str>>>> = std::sync::OnceLock::new();
    T.get_or_init(|| {
        LOCALE_DATES
            .lines()
            .filter_map(|l| {
                let mut f = l.split('\t');
                let loc = f.next()?;
                Some((loc, f.map(|x| x.split('|').collect()).collect()))
            })
            .collect()
    })
}

/// (month names, weekday names) of `locale` (a Java locale such as `fr`,
/// `fr_CA`, `zh-Hant-TW`), each paired with its month / weekday index;
/// the closest CLDR locale (dropping subtags), finding 461/462.
pub fn month_and_day_names(locale: &str) -> Option<(Vec<(&'static str, usize)>, Vec<(&'static str, usize)>)> {
    let row = rows(locale)?;
    let months = row[..4].iter().flat_map(|l| l.iter().enumerate().map(|(i, n)| (*n, i))).collect();
    let days = row[4..8].iter().flat_map(|l| l.iter().enumerate().map(|(i, n)| (*n, i))).collect();
    Some((months, days))
}

/// AM and PM of `locale` (CLDR day periods, format wide: ES's `a`), the
/// closest CLDR locale as [`rows`] resolves it.
pub fn am_pm(locale: &str) -> Option<[&'static str; 2]> {
    let row = rows(locale)?;
    let ap = row.get(8)?;
    Some([*ap.first()?, *ap.get(1)?])
}
